struct CelsiusSensorAdapter: TemperatureReading {
    private let sensor: CelsiusSensor
    init(_ sensor: CelsiusSensor) { self.sensor = sensor }

    func reading() -> Double {                 // target requirement
        sensor.celsius() * 9 / 5 + 32          // translated units
    }
}

