struct AnySequence<Element>: Sequence {
    private let _make: () -> AnyIterator<Element>
    init<S: Sequence>(_ base: S) where S.Element == Element {
        _make = { AnyIterator(base.makeIterator()) }   // box the base
    }
    func makeIterator() -> AnyIterator<Element> { _make() }
}
